/**
 * The complete Italian verb system: every mood and tense of the standard
 * language, simple and compound, plus the non-finite forms.
 *
 * Simple forms are generated from the infinitive by the regular rules and
 * overridden by curated data in src/data/conjugations.json wherever the
 * language is irregular. Where standard Italian has two accepted forms
 * (credei / credetti, debba / deva, va' / vai), both are kept in one cell,
 * separated by "/". Nothing here is a beginner simplification: if a form
 * is used, it is either generated by a documented rule or listed as data.
 *
 * Person indexes: 0 io, 1 tu, 2 lui/lei, 3 noi, 4 voi, 5 loro.
 * For the imperative, index 0 is always null, 2 is formal Lei and 5 formal Loro.
 */

import conjugationData from '../data/conjugations.json';
import {
  PERSONS,
  REFLEXIVE_PRONOUNS,
  baseInfinitive,
  splitInfinitive,
  present,
  imperfect,
  participle,
  auxiliary,
  agreeParticiple
} from './grammar-engine.js';

const IRREGULAR = conjugationData.irregular;
const STRONG_PR = conjugationData.strongPassatoRemoto;
const FUTURE_STEMS = conjugationData.futureStems;
const PR_ALTERNATIVES = conjugationData.passatoRemotoAlternatives;

/* ------------------------------------------------------------------ */
/* Tense metadata                                                      */
/* ------------------------------------------------------------------ */

