export const MOODS = ['indicativo', 'congiuntivo', 'condizionale', 'imperativo'];
export const IMPERATIVE_PERSONS = [null, 'tu', 'Lei', 'noi', 'voi', 'Loro'];

const TENSE_BY_KEY = new Map(TENSES.map((t) => [t.key, t]));

/** "indicativo presente", "congiuntivo imperfetto", "imperativo" — never doubled. */
export function fullTenseLabel(info) {
  if (!info) return '';
  return info.label.startsWith(info.mood) ? info.label : `${info.mood} ${info.label}`;
}
export function tenseInfo(key) {
  return TENSE_BY_KEY.get(normaliseTenseKey(key)) || null;
}

/** Accept the older keys used before the full system existed. */
export function normaliseTenseKey(key) {
  return { present: 'presente', imperfect: 'imperfetto', passato: 'passatoProssimo' }[key] || key;
}

export const SIMPLE_TENSES = TENSES.filter((t) => !t.aux).map((t) => t.key);
export const COMPOUND_TENSES = TENSES.filter((t) => t.aux).map((t) => t.key);

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

const alt = (s) => String(s).split('/');
/** Apply a function to each alternative of a cell and re-join. */
const mapAlt = (cell, fn) => (cell === null || cell === undefined ? null : alt(cell).map(fn).join('/'));

function impersonalMask(base, forms) {
  const irr = IRREGULAR[base];
  if (!irr || !irr.impersonal) return forms;
  const pres = irr.present;
  return forms.map((f, i) => (pres[i] === null ? null : f));
}

function reflexiveWrap(lemma, forms) {
  if (!baseInfinitive(lemma).reflexive) return forms;
  return forms.map((f, i) => (f ? mapAlt(f, (x) => `${REFLEXIVE_PRONOUNS[i]} ${x}`) : f));
}

/** Imperfetto stem: parlavo → parla, facevo → face. */
function imperfectStem(base) {
  const form = imperfect(base).find(Boolean);
  if (!form) return null;
  // impersonal verbs: pioveva -> piove ; nevicava -> nevica
  return form.replace(/v[oa]$/, '');
}

/* ------------------------------------------------------------------ */
/* Futuro and condizionale                                             */
/* ------------------------------------------------------------------ */

export const FUTURE_ENDINGS = ['ò', 'ai', 'à', 'emo', 'ete', 'anno'];
export const CONDITIONAL_ENDINGS = ['ei', 'esti', 'ebbe', 'emmo', 'este', 'ebbero'];

/**
 * Stem shared by futuro and condizionale.
 * Regular: -are → -er- (parlerò), with h after c/g (cercherò) and no i
 * after c/g (mangerò, comincerò); -ere → -er-; -ire → -ir-.
 */
export function futureStem(lemma) {
  const { base } = baseInfinitive(lemma);
  if (IRREGULAR[base] && IRREGULAR[base].futureStem) return IRREGULAR[base].futureStem;
  if (FUTURE_STEMS[base]) return FUTURE_STEMS[base];
  const parts = splitInfinitive(base);
  if (!parts) return null;
  const { stem, ending } = parts;
  if (ending === 'are') {
    if (/[cg]$/.test(stem)) return `${stem}her`;
    if (/[cg]i$/.test(stem)) return `${stem.slice(0, -1)}er`;
    return `${stem}er`;
  }
  return ending === 'ere' ? `${stem}er` : `${stem}ir`;
}

function fromStem(lemma, endings) {
  const { base } = baseInfinitive(lemma);
  const stemCell = futureStem(base);
  const forms = endings.map((e) => mapAlt(stemCell, (s) => s + e));
  return reflexiveWrap(lemma, impersonalMask(base, forms));
}

export function futuro(lemma) {
  return fromStem(lemma, FUTURE_ENDINGS);
}

export function condizionale(lemma) {
  return fromStem(lemma, CONDITIONAL_ENDINGS);
}

/* ------------------------------------------------------------------ */
/* Passato remoto                                                      */
/* ------------------------------------------------------------------ */

const PR_REGULAR = {
  are: ['ai', 'asti', 'ò', 'ammo', 'aste', 'arono'],
  ere: ['ei/etti', 'esti', 'é/ette', 'emmo', 'este', 'erono/ettero'],
  ire: ['ii', 'isti', 'ì', 'immo', 'iste', 'irono']
};

export function passatoRemoto(lemma) {
  const { base } = baseInfinitive(lemma);
  const irr = IRREGULAR[base];
  let forms;
  if (irr && irr.passatoRemoto) {
    forms = [...irr.passatoRemoto];
  } else {
    const strong = (irr && irr.passatoRemotoStrong) || STRONG_PR[base];
    const parts = splitInfinitive(base);
    if (!parts) throw new Error(`Not an infinitive: ${lemma}`);
    if (strong) {
      // "1-3-3" pattern: strong stem in io, lui/lei, loro; regular elsewhere,
      // built on the imperfetto stem (fac-esti, dic-esti, bev-esti, ven-isti).
      const ist = imperfectStem(base);
      const vowel = ist.slice(-1);
      const weak = ist.slice(0, -1);
      forms = [`${strong}i`, `${weak}${vowel}sti`, `${strong}e`, `${weak}${vowel}mmo`, `${weak}${vowel}ste`, `${strong}ero`];
    } else {
      forms = PR_REGULAR[parts.ending].map((e) => mapAlt(e, (x) => parts.stem + x));
    }
  }
  return reflexiveWrap(lemma, impersonalMask(base, forms));
}

export function passatoRemotoNote(lemma) {
  return PR_ALTERNATIVES[baseInfinitive(lemma).base] || null;
}

/* ------------------------------------------------------------------ */
/* Congiuntivo                                                         */
/* ------------------------------------------------------------------ */

/**
 * Congiuntivo presente. Built from the present tense, which captures most
 * irregularities automatically:
 *   singular and loro: stem of the io form + -i/-ino (regular -are verbs) or
 *   -a/-ano (all other verbs, including irregular -are verbs: vada, faccia);
 *   noi = presente noi; voi = noi stem + -iate.
 */
export function congiuntivoPresente(lemma, opts = {}) {
  const { base } = baseInfinitive(lemma);
  const irr = IRREGULAR[base];
  let forms;
  if (irr && irr.subjunctivePresent) {
    forms = [...irr.subjunctivePresent];
  } else {
    const pres = present(base, { isc: opts.isc });
    const parts = splitInfinitive(base);
    const aSet = Boolean(irr && !irr.impersonal) || parts.ending !== 'are';
    // Impersonal verbs have no io form: derive the stem from the third person.
    const ioStem = pres[0] ? pres[0].replace(/o$/, '') : pres[2].replace(/[ae]$/, '');
    const join = (stem, end) => {
      if (/[cg]$/.test(stem) && /^i/.test(end) && !aSet) return `${stem}h${end}`;
      if (stem.endsWith('i') && end.startsWith('i')) return stem + end.slice(1);
      return stem + end;
    };
    const sg = join(ioStem, aSet ? 'a' : 'i');
    const noi = pres[3];
    const voi = noi ? `${noi.slice(0, -4)}iate` : null;
    forms = [sg, sg, sg, noi, voi, join(ioStem, aSet ? 'ano' : 'ino')];
  }
  return reflexiveWrap(lemma, impersonalMask(base, forms));
}

/** Congiuntivo imperfetto: imperfetto stem + -ssi, -ssi, -sse, -ssimo, -ste, -ssero. */
export function congiuntivoImperfetto(lemma) {
  const { base } = baseInfinitive(lemma);
  const irr = IRREGULAR[base];
  let forms;
  if (irr && irr.subjunctiveImperfect) forms = [...irr.subjunctiveImperfect];
  else {
    const st = imperfectStem(base);
    forms = ['ssi', 'ssi', 'sse', 'ssimo', 'ste', 'ssero'].map((e) => st + e);
  }
  return reflexiveWrap(lemma, impersonalMask(base, forms));
}

/* ------------------------------------------------------------------ */
/* Imperativo                                                          */
/* ------------------------------------------------------------------ */

/**
 * [null, tu, Lei, noi, voi, Loro]. Lei and Loro come from the congiuntivo
 * presente. Reflexive and object pronouns follow tu/noi/voi (alzati,
 * alziamoci, alzatevi) and precede Lei/Loro (si alzi, si alzino).
 */
export function imperativo(lemma, opts = {}) {
  const { base, reflexive } = baseInfinitive(lemma);
  const irr = IRREGULAR[base];
  if ((irr && (irr.noImperative || irr.impersonal)) || !splitInfinitive(base)) return [null, null, null, null, null, null];
  const pres = present(base, { isc: opts.isc });
  const cong = congiuntivoPresente(base, opts);
  const parts = splitInfinitive(base);
  let tu;
  if (irr && irr.imperativeTu) tu = irr.imperativeTu;
  else tu = parts.ending === 'are' && !irr ? pres[2] : pres[1];
  const voi = irr && irr.imperativeVoi ? irr.imperativeVoi : pres[4];
  const forms = [null, tu, cong[2], pres[3], voi, cong[5]];
  if (!reflexive) return forms;
  return [
    null,
    mapAlt(tu, (x) => `${x.replace(/'$/, '')}ti`),
    mapAlt(cong[2], (x) => `si ${x}`),
    mapAlt(pres[3], (x) => `${x}ci`),
    mapAlt(voi, (x) => `${x}vi`),
    mapAlt(cong[5], (x) => `si ${x}`)
  ];
}

/** Negative imperative for tu: non + infinitive (non parlare; non alzarti / non ti alzare). */
export function imperativoNegativoTu(lemma) {
  const { base, reflexive } = baseInfinitive(lemma);
  const irr = IRREGULAR[base];
  if (irr && (irr.noImperative || irr.impersonal)) return null;
  if (!reflexive) return `non ${base}`;
  return `non ${base.slice(0, -1)}ti/non ti ${base}`;
}

/* ------------------------------------------------------------------ */
/* Non-finite forms                                                    */
/* ------------------------------------------------------------------ */

export function gerundio(lemma) {
  const { base, reflexive } = baseInfinitive(lemma);
  const irr = IRREGULAR[base];
  let g;
  if (irr && irr.gerund) g = irr.gerund;
  else {
    const st = imperfectStem(base);
    g = st.endsWith('i') ? `${st.slice(0, -1)}endo` : `${st}ndo`;
  }
  return reflexive ? `${g}si` : g;
}

function auxNonFinite(aux, kind) {
  if (kind === 'inf') return aux === 'essere' ? 'essere' : 'avere';
  return aux === 'essere' ? 'essendo' : 'avendo';
}

/** infinito passato: avere/essere + participle (aver mangiato, essere partito). */
export function infinitoPassato(lemma, { gender = 'm', number = 'sg', record } = {}) {
  const { reflexive } = baseInfinitive(lemma);
  const aux = auxiliary(lemma, record);
  const p = aux === 'essere' ? agreeParticiple(participle(lemma), gender, number) : participle(lemma);
  if (reflexive) return `essersi ${p}`;
  return `${auxNonFinite(aux, 'inf')} ${p}`;
}

export function gerundioPassato(lemma, { gender = 'm', number = 'sg', record } = {}) {
  const { reflexive } = baseInfinitive(lemma);
  const aux = auxiliary(lemma, record);
  const p = aux === 'essere' ? agreeParticiple(participle(lemma), gender, number) : participle(lemma);
  if (reflexive) return `essendosi ${p}`;
  return `${auxNonFinite(aux, 'ger')} ${p}`;
}

/* ------------------------------------------------------------------ */
/* Dispatch                                                            */
/* ------------------------------------------------------------------ */

function simpleForms(lemma, key, opts = {}) {
  switch (key) {
    case 'presente':
      return present(lemma, { isc: opts.isc });
    case 'imperfetto':
      return imperfect(lemma);
    case 'passatoRemoto':
      return passatoRemoto(lemma);
    case 'futuro':
      return futuro(lemma);
    case 'condizionale':
      return condizionale(lemma);
    case 'congiuntivoPresente':
      return congiuntivoPresente(lemma, opts);
    case 'congiuntivoImperfetto':
      return congiuntivoImperfetto(lemma);
    case 'imperativo':
      return imperativo(lemma, opts);
    default:
      throw new Error(`Unknown simple tense: ${key}`);
  }
}

/**
 * Conjugate any tense.
 * opts: { gender: 'm'|'f' (agreement with essere), isc, record (vocabulary record) }
 */
export function conjugate(lemma, tenseKey, opts = {}) {
  const key = normaliseTenseKey(tenseKey);
  const info = TENSE_BY_KEY.get(key);
  if (!info) throw new Error(`Unknown tense: ${tenseKey}`);
  if (!info.aux) return simpleForms(lemma, key, opts);
  const { base, reflexive } = baseInfinitive(lemma);
  const aux = reflexive ? 'essere' : auxiliary(lemma, opts.record);
  const auxForms = simpleForms(aux, info.aux);
  const p = participle(lemma);
  const forms = auxForms.map((a, i) => {
    const number = i >= 3 ? 'pl' : 'sg';
    const part = aux === 'essere' ? agreeParticiple(p, opts.gender || 'm', number) : p;
    return mapAlt(a, (x) => `${x} ${part}`);
  });
  return reflexiveWrap(lemma, impersonalMask(base, forms));
}

/** Every finite tense, keyed by tense key. */
export function allTenses(lemma, opts = {}) {
  return Object.fromEntries(TENSES.map((t) => [t.key, conjugate(lemma, t.key, opts)]));
}

export function nonFinite(lemma, opts = {}) {
  const { base, reflexive } = baseInfinitive(lemma);
  return {
    infinito: lemma,
    infinitoPassato: infinitoPassato(lemma, opts),
    gerundio: gerundio(lemma),
    gerundioPassato: gerundioPassato(lemma, opts),
    participioPassato: participle(base),
    imperativoNegativoTu: imperativoNegativoTu(lemma),
    reflexive
  };
}

/** Split a cell into its alternatives (for indexing and answer keys). */
export function alternatives(cell) {
  return cell === null || cell === undefined ? [] : alt(cell);
}

/** Display a cell: "credei/credetti" → "credei / credetti". */
export function displayCell(cell) {
  return cell === null || cell === undefined ? '—' : alt(cell).join(' / ');
}

export { PERSONS };

/* ------------------------------------------------------------------ */
/* Irregularity detection for tables                                   */
/* ------------------------------------------------------------------ */

/**
 * The forms a verb would have if it followed the regular pattern of its
 * conjugation family. Used only to highlight irregular cells in tables.
 */
export function regularConjugation(lemma, key) {
  const { base } = baseInfinitive(lemma);
  const parts = splitInfinitive(base);
  if (!parts) return [null, null, null, null, null, null];
  const { stem, ending } = parts;
  const isc = conjugationData.iscVerbs.includes(base);
  const hard = ending === 'are' && /[cg]$/.test(stem);
  const join = (st, end) => {
    if (hard && /^[ie]/.test(end)) return `${st}h${end}`;
    if (st.endsWith('i') && end.startsWith('i')) return st + end.slice(1);
    return st + end;
  };
  const presEnd = { are: ['o', 'i', 'a', 'iamo', 'ate', 'ano'], ere: ['o', 'i', 'e', 'iamo', 'ete', 'ono'], ire: isc ? ['isco', 'isci', 'isce', 'iamo', 'ite', 'iscono'] : ['o', 'i', 'e', 'iamo', 'ite', 'ono'] }[ending];
  const pres = presEnd.map((e) => join(stem, e));
  const vowel = ending[0];
  switch (key) {
    case 'presente':
      return pres;
    case 'imperfetto':
      return ['vo', 'vi', 'va', 'vamo', 'vate', 'vano'].map((e) => `${stem}${vowel}${e}`);
    case 'passatoRemoto':
      return PR_REGULAR[ending].map((e) => alt(e).map((x) => stem + x).join('/'));
    case 'futuro':
    case 'condizionale': {
      let fs = ending === 'ire' ? `${stem}ir` : `${stem}er`;
      if (ending === 'are' && hard) fs = `${stem}her`;
      else if (ending === 'are' && /[cg]i$/.test(stem)) fs = `${stem.slice(0, -1)}er`;
      return (key === 'futuro' ? FUTURE_ENDINGS : CONDITIONAL_ENDINGS).map((e) => fs + e);
    }
    case 'congiuntivoPresente': {
      const io = pres[0].replace(/o$/, '');
      const sg = ending === 'are' ? join(io, 'i') : `${io}a`;
      return [sg, sg, sg, pres[3], `${pres[3].slice(0, -4)}iate`, ending === 'are' ? join(io, 'ino') : `${io}ano`];
    }
    case 'congiuntivoImperfetto':
      return ['ssi', 'ssi', 'sse', 'ssimo', 'ste', 'ssero'].map((e) => `${stem}${vowel}${e}`);
    case 'imperativo': {
      const io = pres[0].replace(/o$/, '');
      const lei = ending === 'are' ? join(io, 'i') : `${io}a`;
      const loro = ending === 'are' ? join(io, 'ino') : `${io}ano`;
      return [null, ending === 'are' ? pres[2] : pres[1], lei, pres[3], pres[4], loro];
    }
    default:
      return [null, null, null, null, null, null];
  }
}

/** Boolean per cell: true where the actual form differs from the regular pattern. */
export function irregularCells(lemma, key) {
  const k = normaliseTenseKey(key);
  const info = TENSE_BY_KEY.get(k);
  if (!info || info.aux) return [false, false, false, false, false, false];
  const actual = conjugate(lemma, k);
  const regular = regularConjugation(lemma, k);
  const strip = (f) => (f ? f.replace(/^(mi|ti|si|ci|vi) /, '').replace(/(ti|ci|vi)$/, '') : f);
  return actual.map((f, i) => {
    if (!f || !regular[i]) return false;
    const a = alt(f).map((x) => strip(x));
    const r = alt(regular[i]).map((x) => strip(x));
    return !a.some((x) => r.includes(x));
  });
}
